from h34 import *
M=mcq;F=tf;S=short;N=num
def box(x,y,w,h,t,c="#fff3d6"): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="12" fill="{c}" stroke="#333" stroke-width="2"/><text x="{x+w/2}" y="{y+h/2+5}" text-anchor="middle">{t}</text>'
b=box(150,15,120,40,"Dadaji")+box(310,15,120,40,"Dadiji")+'<line x1="270" y1="35" x2="310" y2="35" stroke="#333" stroke-width="2"/><line x1="290" y1="35" x2="290" y2="85" stroke="#333" stroke-width="2"/>'
b+=box(90,85,120,40,"Father","#dff0ff")+box(250,85,120,40,"Mother","#dff0ff")+'<line x1="210" y1="105" x2="250" y2="105" stroke="#333" stroke-width="2"/><line x1="230" y1="105" x2="230" y2="150" stroke="#333" stroke-width="2"/><line x1="140" y1="150" x2="440" y2="150" stroke="#333" stroke-width="2"/>'
for i,(n,c) in enumerate((("Banku","#e5f5e0"),("Bela","#e5f5e0"),("Bishu","#e5f5e0"),("Shiru the dog","#ffe5d6"))):
    x=60+i*130; b+=f'<line x1="{x+55}" y1="150" x2="{x+55}" y2="175" stroke="#333" stroke-width="2"/>'+box(x,175,110,40,n,c)
b+='<line x1="290" y1="85" x2="290" y2="100" stroke="#333" stroke-width="0"/><text x="270" y="250" text-anchor="middle" font-weight="bold">Bela\'s family: grandparents, parents, children and a pet</text>'
svgfile('c3-ff-family.svg',560,265,b)
chapter(3,'evs','family-and-friends','Family and Friends',
 ("Namaste! Welcome to my home!","My name is Bela. I have two brothers, Banku Bhaiya and little Bishu, and we love to play chhupan-chhupai (hide and seek) outside our house. My family, my friends and our dog Shiru fill my days with games, songs, food and work. Come and see how a family lives, plays, helps and cares."),
 [("Playing together",["Bela lives with her parents, her brothers Banku and Bishu, and her grandparents. Together they are one family.","The children play chhupan-chhupai, hide and seek, in the open space outside their house. They also play peek-a-boo with little Bishu, hiding and suddenly showing their face and saying peek-a-boo.","They have planted a garden with many flowering plants. Relatives, friends and neighbours come to the garden, sit, talk, share jokes and laugh together.","Sometimes their father and mother, tired after a hard day's work, also sit and relax in the garden, so the whole family enjoys spending the evening together."]),
  ("Singing together",["On rainy days the family sits under a small shelter in the garden. It is great fun to sit outside when it rains.","They play games such as antakshari and snakes and ladders. Bela's mother and Dadiji, her grandmother, make hot pakodas and tea, and everybody, grandparents too, enjoys them together.","Dadiji sings songs about the rain and teaches them to the children, so they join in the singing. Songs are passed from grandparents to grandchildren in this way.","We can sing a rain song in class with our friends, and we can also write down the names of our own family members, how they are related to us and what we call them, like Mausi for the mother's sister."]),
  ("Laughing together",["Bela's grandfather, Dadaji, taught Banku and Bela the games he played with his friends when he was young. He joins in their games too.","Shiru, the dog, is a member of the family and has a special place in the home. He runs around, barking and wagging his tail with joy.","Banku and Bela never hurt Shiru and they share their food with him. We should be kind and caring towards animals and should not tease or hurt them.","We can ask our grandparents which games they played when they were small and play them with them."]),
  ("Types of families",["Families are big and small and different, and we love them all. A family can have a few or many members.","There can be parents (mother and father), grandparents like Dadiji and Dadaji, brothers and sisters like Banku and Bela, and other elders in a family.","Everybody loves each other and takes care of each other. Families also love and care for animals, trees and plants. Cows, buffaloes, dogs, parrots, cats and goats can be a part of a family.","We can look around our neighbourhood and see many types of families, so we must not say that only one kind of family is right."]),
  ("Helping each other",["In our homes we do many things together. Bela's Dadiji oils her hair and braids it every morning before school, humming a song, and this makes Bela happy.","Bela's parents help each other in all the housework, from cooking and cleaning to shopping for groceries. Dadaji loves gardening, and Bela helps him in the garden.","Banku helps in cleaning and chopping vegetables. Everyone in the family does some work and everyone helps.","Some people in the family, like grandparents, small children or someone who is sick, need special care and support, and we should help them."]),
  ("Friends and neighbours",["Munni is one of Bela's closest friends. Munni and her mother, Kusum Mausi, live near her house. Kusum Mausi is the mother's close friend, who is like a sister.","Kusum Mausi is an excellent cook and makes sweets and special dishes during festivals. She and Munni join the family in all festivals.","Munni is very good at making rangoli, using colours from dried flowers, leaves and flowers. Bela loves to help her.","We learn many things from our family members and neighbours, and we can teach them things too."]),
  ("Relatives and family work",["Our family also includes relatives who may not live with us. They are related to us through our parents, our mother or father.","A relative can be an uncle like Mohan Chacha, who is father's brother, or an aunt like a Mausi, who is mother's sister. Their names for us and our names for them show how we are related.","We can make a table of who does which work in our home: cooking food, watering plants, mending things, cleaning the house and buying things from the market.","When we share the work, the home runs smoothly and everyone has time to play, rest and be together."]),
  ("A day in the park",["On a holiday Bela went to the park with Dadaji. Their friends Niku, Rinki, Rohit, Ronnie and Tara were playing pitthoo, a game with a pile of stones and a ball.","They made two teams. Dadaji hit the stones with the ball and scattered them, and they ran to pile the stones up fast while the others tried to hit them with the ball.","After some time they were tired, so Dadaji asked them to rest. Then he bought them ice cream and they went home as it grew dark, after a lot of fun playing, laughing and eating together.","Playing with friends and elders keeps us happy and healthy, and good games teach us to take turns and work in a team."])],
 [("Make a table to show how our relatives are related to us.",[("Write the name of the relative, for example Urmila.","The first column names the person."),("Write how she is related to you, such as mother's sister.","The second column shows the relationship."),("Write what you call her, such as Mausi.","The third column shows how we address them with respect.")]),
  ("Make a rangoli from fallen leaves and flowers.",[("Collect leaves and flowers that have fallen on the ground. Do not pluck flowers from plants.","We use what has already fallen so that we do not harm the plants."),("Place a big flower in the middle and arrange leaves and petals around it in a pattern.","A pattern makes the rangoli look neat and pretty."),("Look at your rangoli and tell a friend what you used and why it is pretty.","Making something together helps us learn from each other, as Bela learns from Munni.")])],
 ("Tell a friend how the members of a family show love and care for each other, and how we should treat a pet.",["Family members help each other with work","They play, sing, eat and spend time together","Elders and those who need care are helped","We are kind to animals and never hurt them"],["Only people are part of a family","Only elders do the housework","We can tease a pet for fun"]),
 ["A family can be big or small, and everyone in it loves and cares for each other.","Family members play, sing, eat and work together.","Grandparents teach songs and games, and we learn from elders and neighbours.","Pets like Shiru can be part of the family, and we must be kind to animals.","Relatives are the people related to us through our mother or father.","Friends and neighbours share festivals, games and happy times."],
 [M("ff-1",1,"Who is Shiru?","The pet dog of the family",[("Bela's brother","Bela's brothers are Banku and Bishu."),("Bela's friend Munni","Munni is Bela's friend and Shiru is a dog."),("Bela's grandfather","Bela's grandfather is called Dadaji.")],"Shiru is the dog, and he is a member of the family.",None),
  M("ff-2",1,"What do the children do on rainy days in the garden shelter?","Play games and eat pakodas",[("Sleep all day","They are awake, playing and singing together."),("Go to school","The rainy-day shelter is in their own garden."),("Water the plants only","There is no need to water plants when it rains.")],"They play antakshari and snakes and ladders and enjoy hot pakodas.",None),
  M("ff-3",1,"Who is Dadiji?","Bela's grandmother",[("Bela's mother","Bela's mother is a different person; Dadiji is her grandmother."),("Bela's neighbour","Dadiji is part of Bela's own family."),("Bela's friend","Dadiji is much older and is Bela's grandmother.")],"Dadiji is the grandmother who sings rain songs and braids Bela's hair.",None),
  F("ff-4",1,"We can tease or hurt animals because they cannot speak.",False,"Animals feel pain and fear like us, so we must be kind to them and never hurt or tease them."),
  M("ff-5",1,"Which of these is a good way to treat a pet?","Share food with it and be kind",[("Pull its tail for fun","That hurts the pet."),("Shout at it when it comes near","Shouting frightens it."),("Leave it hungry","A pet depends on us for food.")],"Bela and Banku share their food with Shiru and never hurt him.",None),
  M("ff-6",2,"Who do we call a relative?","A person related to us through our mother or father",[("Only a friend who lives near us","A neighbour or a friend is not necessarily a relative."),("Only a person who lives in our house","Relatives may live somewhere else."),("Any person we have met once","Relatives are family, not just people we have met.")],"Relatives are related to us through our parents, and they may not live with us.",None),
  M("ff-7",2,"Munni's mother, Kusum Mausi, is like a sister to Bela's mother. What does this tell us?","Close friends can be like family",[("Friends cannot be loved like family","Friends who care for us can be as dear as relatives."),("Kusum Mausi must be Bela's mother's real sister","She is a close friend who is like a sister."),("Families must have only relatives","Families also have close friends and neighbours who care.")],"Close friends and neighbours can be like family.",None),
  M("ff-8",2,"Which of these is a game that Bela's family plays together?","Antakshari",[("Cricket on TV","The family plays and sings together."),("Video games only","The family plays outdoors and indoor games together."),("None","They play many games.")],"Antakshari is a singing game that the family plays on rainy days.",None),
  S("ff-9",2,"What is the game of hiding and seeking called in Bela's story? (Hint: chhupan-____)",["chhupai","chhupan-chhupai","chhupanchhupai"],"The game is called chhupan-chhupai, which is hide and seek.",[("pitthoo","Pitthoo is played with stones and a ball; hide and seek is chhupan-chhupai.")]),
  M("ff-10",3,"Why is it good for every family member to do some work at home?","Work is shared so the home runs smoothly and all can rest and play",[("Because only children should work","Everyone in the family can help, in ways that suit them."),("Because it makes work harder","Sharing makes work easier and faster."),("Because elders cannot work","Elders also help in many ways, like Dadaji in the garden.")],"When everyone helps, the work is done quickly and there is time for fun.",None),
  F("ff-11",3,"A family can have only a mother, a father and two children.",False,"Families can be big or small. They may include grandparents, uncles, aunts and even pets."),
  M("ff-12",3,"On a holiday Bela plays pitthoo. What is the best thing about playing with friends?","We have fun and learn to play fairly as a team",[("We can win without rules","A good game has rules for everyone."),("We never get tired","They get tired and rest, like Bela did."),("We play alone","Pitthoo is played in two teams.")],"Playing with friends is fun, and it teaches us to cooperate.",None)],
 svgs=[("c3-ff-family","A picture of Bela's family: Dadaji, Dadiji, father, mother, Banku, Bela, Bishu and Shiru the dog","Bela's family: grandparents, parents, children and a pet.")])
